import codecs
import random
import struct

KEYS = ['470FC614', '4A0FC614', '4B9FC614', '4C8FC614', '4D7FC614']


def task_func(hex_keys=KEYS):
    if not hex_keys:
        raise ValueError("hex_keys must not be empty")

    hex_key = random.choice(hex_keys)
    if not isinstance(hex_key, str):
        raise TypeError("hex_keys must contain hex strings")

    hex_key = hex_key.strip()
    if hex_key.startswith(("0x", "0X")):
        hex_key = hex_key[2:]

    try:
        raw_bytes = bytes.fromhex(hex_key)
        float_value = struct.unpack(">f", raw_bytes)[0]
    except (ValueError, struct.error) as e:
        raise ValueError(f"Invalid hex key: {hex_key!r}") from e

    return {"bytes": codecs.encode(str(float_value), "utf-8")}
