import subprocess
import os
import signal
import time

def _normalize_name(value: str) -> str:
    value = (value or "").strip().strip('"').strip("'")
    if not value:
        return ""
    value = value.rsplit("/", 1)[-1]
    value = value.rsplit("\\", 1)[-1]
    return value

def _name_matches(candidate: str, target: str) -> bool:
    cand = _normalize_name(candidate)
    tgt = _normalize_name(target)
    if not cand or not tgt:
        return False

    if os.name == "nt":
        cand_lower = cand.lower()
        tgt_lower = tgt.lower()
        if cand_lower == tgt_lower:
            return True

        cand_stem, cand_ext = os.path.splitext(cand_lower)
        tgt_stem, tgt_ext = os.path.splitext(tgt_lower)

        if not tgt_ext and cand_stem == tgt_lower:
            return True
        if not cand_ext and tgt_stem == cand_lower:
            return True
        return False

    return cand == tgt

def _collect_pids_from_procfs(process_name: str):
    pids = set()
    proc_root = "/proc"
    if not os.path.isdir(proc_root):
        return pids

    try:
        entries = os.listdir(proc_root)
    except OSError:
        return pids

    for entry in entries:
        if not entry.isdigit():
            continue

        pid = int(entry)
        comm_path = os.path.join(proc_root, entry, "comm")
        try:
            with open(comm_path, "r", encoding="utf-8", errors="ignore") as f:
                if _name_matches(f.read().strip(), process_name):
                    pids.add(pid)
                    continue
        except OSError:
            pass

        cmdline_path = os.path.join(proc_root, entry, "cmdline")
        try:
            with open(cmdline_path, "rb") as f:
                cmdline = f.read()
            if cmdline:
                first_arg = cmdline.split(b"\0", 1)[0].decode("utf-8", errors="ignore")
                if _name_matches(first_arg, process_name):
                    pids.add(pid)
        except OSError:
            pass

    return pids

def _collect_pids_with_ps(process_name: str):
    pids = set()
    try:
        result = subprocess.run(
            ["ps", "-A", "-o", "pid=", "-o", "comm="],
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="ignore",
            check=False,
        )
    except OSError:
        return pids

    for raw_line in result.stdout.splitlines():
        line = raw_line.strip()
        if not line:
            continue

        parts = line.split(None, 1)
        if len(parts) != 2:
            continue

        pid_text, comm = parts
        if _name_matches(comm, process_name):
            try:
                pids.add(int(pid_text))
            except ValueError:
                pass

    return pids

def _collect_pids_on_windows(process_name: str):
    pids = set()
    try:
        result = subprocess.run(
            ["tasklist", "/FO", "CSV", "/NH"],
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="ignore",
            check=False,
        )
    except OSError:
        return pids

    for raw_line in result.stdout.splitlines():
        line = raw_line.strip()
        if not line:
            continue

        if line.startswith('"') and line.endswith('"'):
            fields = line[1:-1].split('","')
        else:
            fields = [field.strip().strip('"') for field in line.split(",")]

        if len(fields) < 2:
            continue

        image_name = fields[0]
        pid_text = fields[1]
        if _name_matches(image_name, process_name):
            try:
                pids.add(int(pid_text))
            except ValueError:
                pass

    return pids

def task_func(process_name: str) -> int:
    target = _normalize_name(process_name)
    if not target:
        return 0

    if os.name == "nt":
        pids = _collect_pids_on_windows(target)
    else:
        pids = _collect_pids_from_procfs(target)
        if not pids:
            pids = _collect_pids_with_ps(target)

    current_pid = os.getpid()
    stopped = 0

    for pid in sorted(pids):
        if pid == current_pid:
            continue
        try:
            os.kill(pid, signal.SIGTERM)
            stopped += 1
        except (ProcessLookupError, PermissionError, OSError):
            continue

    if stopped:
        time.sleep(1)

    return stopped
