import urllib.request
from bs4 import BeautifulSoup
import csv
import os

# Constants
CSV_FILE_PATH = 'scraped_data.csv'


def _clean_text(text):
    """Normalize whitespace and trim text."""
    return " ".join((text or "").split()).strip()


def _unique_headers(headers):
    """Make header names unique and non-empty."""
    seen = {}
    result = []
    for idx, header in enumerate(headers, start=1):
        name = _clean_text(header) or f"column_{idx}"
        count = seen.get(name, 0) + 1
        seen[name] = count
        if count > 1:
            name = f"{name}_{count}"
        result.append(name)
    return result


def _extract_table_rows(soup):
    """Extract rows from HTML tables into dictionaries."""
    rows = []

    for table_index, table in enumerate(soup.find_all("table"), start=1):
        tr_list = table.find_all("tr")
        if not tr_list:
            continue

        headers = None
        start_row = 0

        # Prefer explicit table headers
        thead = table.find("thead")
        if thead:
            header_tr = thead.find("tr")
            if header_tr:
                header_cells = header_tr.find_all(["th", "td"])
                headers = _unique_headers(
                    [_clean_text(cell.get_text(" ", strip=True)) for cell in header_cells]
                )
                start_row = 0

        # Fallback: use the first row as headers only if it contains th cells
        if headers is None:
            first_tr = tr_list[0]
            first_cells = first_tr.find_all(["th", "td"])
            first_has_th = any(cell.name == "th" for cell in first_cells)

            if first_has_th and first_cells:
                headers = _unique_headers(
                    [_clean_text(cell.get_text(" ", strip=True)) for cell in first_cells]
                )
                start_row = 1
            else:
                headers = [f"column_{i+1}" for i in range(len(first_cells))]
                start_row = 0

        for row_index, tr in enumerate(tr_list[start_row:], start=1):
            cells = tr.find_all(["th", "td"])
            if not cells:
                continue

            values = [_clean_text(cell.get_text(" ", strip=True)) for cell in cells]

            # If row width differs, pad or truncate to match headers
            if len(values) < len(headers):
                values.extend([""] * (len(headers) - len(values)))
            elif len(values) > len(headers):
                values = values[: len(headers)]

            row_data = {
                "table_index": table_index,
                "row_index": row_index,
            }
            row_data.update(dict(zip(headers, values)))
            rows.append(row_data)

    return rows


def _extract_fallback_rows(soup, source_url):
    """Fallback extraction when no tables are found."""
    rows = []

    title = _clean_text(soup.title.get_text(" ", strip=True)) if soup.title else ""

    # Extract meaningful visible content
    for element in soup.find_all(["h1", "h2", "h3", "p", "li", "a"]):
        text = _clean_text(element.get_text(" ", strip=True))
        if not text:
            continue

        row = {
            "source_url": source_url,
            "page_title": title,
            "element": element.name,
            "text": text,
        }

        href = element.get("href")
        if href:
            row["href"] = href

        rows.append(row)

    # If still nothing useful, save the full page text
    if not rows:
        full_text = _clean_text(soup.get_text(" ", strip=True))
        rows.append(
            {
                "source_url": source_url,
                "page_title": title,
                "element": "full_text",
                "text": full_text,
            }
        )

    return rows


def _write_rows_to_csv(rows, csv_path):
    """Write a list of dictionaries to a CSV file with stable column order."""
    fieldnames = []
    seen = set()

    for row in rows:
        for key in row.keys():
            if key not in seen:
                seen.add(key)
                fieldnames.append(key)

    if not fieldnames:
        fieldnames = ["data"]
        rows = [{"data": ""}]

    with open(csv_path, "w", newline="", encoding="utf-8") as csv_file:
        writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)


def task_func(url):
    """
    Scrape data from the given URL and save it to a CSV file.

    Returns:
        str: The path of the CSV file where the scraped data is saved.
    """
    request = urllib.request.Request(
        url,
        headers={
            "User-Agent": "Mozilla/5.0 (compatible; CodexScraper/1.0)"
        },
    )

    with urllib.request.urlopen(request) as response:
        html = response.read()

    soup = BeautifulSoup(html, "html.parser")

    rows = _extract_table_rows(soup)
    if not rows:
        rows = _extract_fallback_rows(soup, url)

    _write_rows_to_csv(rows, CSV_FILE_PATH)
    return os.path.abspath(CSV_FILE_PATH)
```

