import subprocess
import os
import signal
import time

def task_func(process_name: str) -> int:
    if not process_name:
        return 0

    target_name = os.path.basename(process_name.strip())
    if not target_name:
        return 0

    target_name_cmp = target_name.lower() if os.name == "nt" else target_name
    current_pid = os.getpid()

    def _list_matching_pids() -> list[int]:
        pids: list[int] = []
        try:
            if os.name == "nt":
                result = subprocess.run(
                    ["tasklist", "/FO", "CSV", "/NH", "/FI", f"IMAGENAME eq {target_name}"],
                    capture_output=True,
                    text=True,
                    check=False,
                )
                for line in result.stdout.splitlines():
                    line = line.strip()
                    if not line or line.startswith("INFO:"):
                        continue
                    if not (line.startswith('"') and line.endswith('"')):
                        continue
                    fields = line[1:-1].split('","')
                    if len(fields) < 2:
                        continue
                    image = fields[0].strip()
                    pid_str = fields[1].strip()
                    if image.lower() != target_name_cmp:
                        continue
                    try:
                        pid = int(pid_str)
                    except ValueError:
                        continue
                    if pid != current_pid:
                        pids.append(pid)
            else:
                result = subprocess.run(
                    ["ps", "-A", "-o", "pid=,comm="],
                    capture_output=True,
                    text=True,
                    check=False,
                )
                for line in result.stdout.splitlines():
                    line = line.strip()
                    if not line:
                        continue
                    parts = line.split(None, 1)
                    if len(parts) != 2:
                        continue
                    pid_str, name = parts[0].strip(), parts[1].strip()
                    if name != target_name:
                        continue
                    try:
                        pid = int(pid_str)
                    except ValueError:
                        continue
                    if pid != current_pid:
                        pids.append(pid)
        except Exception:
            return []
        return pids

    initial_pids = _list_matching_pids()
    if not initial_pids:
        return 0

    for pid in initial_pids:
        try:
            os.kill(pid, signal.SIGTERM)
        except OSError:
            pass

    time.sleep(1)

    remaining_pids = set(_list_matching_pids())
    stopped = sum(1 for pid in initial_pids if pid not in remaining_pids)
    return stopped
