import subprocess
import os
import signal
import time

def _pid_exists(pid: int) -> bool:
    try:
        os.kill(pid, 0)
        return True
    except OSError:
        return False

def _unique_ints(values):
    seen = set()
    result = []
    for value in values:
        if value not in seen:
            seen.add(value)
            result.append(value)
    return result

def _find_pids_unix(process_name: str):
    target = os.path.basename(process_name)

    # Prefer pgrep when available.
    try:
        out = subprocess.check_output(
            ["pgrep", "-x", target],
            text=True,
            stderr=subprocess.DEVNULL,
        )
        pids = []
        for part in out.split():
            try:
                pids.append(int(part))
            except ValueError:
                pass
        if pids:
            return pids
    except (subprocess.CalledProcessError, FileNotFoundError, OSError):
        pass

    # Fallback to ps parsing.
    try:
        out = subprocess.check_output(
            ["ps", "-A", "-o", "pid=,comm="],
            text=True,
            stderr=subprocess.DEVNULL,
        )
    except (subprocess.CalledProcessError, FileNotFoundError, OSError):
        return []

    pids = []
    for line in out.splitlines():
        line = line.strip()
        if not line:
            continue
        parts = line.split(None, 1)
        if len(parts) != 2:
            continue
        pid_s, cmd = parts
        if os.path.basename(cmd.strip()) == target:
            try:
                pids.append(int(pid_s))
            except ValueError:
                pass
    return pids

def _find_pids_windows(process_name: str):
    target = os.path.basename(process_name).lower()

    try:
        out = subprocess.check_output(
            ["tasklist", "/FO", "CSV", "/NH"],
            text=True,
            stderr=subprocess.DEVNULL,
        )
    except (subprocess.CalledProcessError, FileNotFoundError, OSError):
        return []

    pids = []
    for line in out.splitlines():
        line = line.strip()
        if not line:
            continue
        # Expected CSV format:
        # "Image Name","PID","Session Name","Session#","Mem Usage"
        parts = [p.strip('"') for p in line.split('","')]
        if len(parts) < 2:
            continue
        image = parts[0].lower()
        if image == target or image == target + ".exe":
            try:
                pids.append(int(parts[1]))
            except ValueError:
                pass
    return pids

def task_func(process_name: str) -> int:
    if not process_name:
        return 0

    if os.name == "nt":
        pids = _find_pids_windows(process_name)
    else:
        pids = _find_pids_unix(process_name)

    pids = _unique_ints(pids)
    if not pids:
        return 0

    # Send a termination signal to each matching process.
    for pid in pids:
        try:
            os.kill(pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
        except PermissionError:
            pass
        except OSError:
            pass

    # Wait briefly for termination.
    time.sleep(1)

    # Count processes that are no longer running after the wait.
    stopped = 0
    for pid in pids:
        if not _pid_exists(pid):
            stopped += 1

    return stopped
