import os
import hashlib
import json
from pathlib import Path

def task_func(directory: str) -> str:
    base_dir = Path(os.fspath(directory)).expanduser().resolve()
    if not base_dir.exists():
        raise FileNotFoundError(f"Directory does not exist: {directory}")
    if not base_dir.is_dir():
        raise NotADirectoryError(f"Not a directory: {directory}")

    output_path = base_dir / "hashes.json"
    output_resolved = output_path.resolve()

    file_paths = []
    for path in base_dir.rglob("*"):
        if not path.is_file():
            continue
        if path.resolve() == output_resolved:
            continue
        file_paths.append(path)

    hashes = {}
    for path in sorted(file_paths, key=lambda p: p.relative_to(base_dir).as_posix()):
        sha256 = hashlib.sha256()
        with path.open("rb") as file_obj:
            for chunk in iter(lambda: file_obj.read(8192), b""):
                sha256.update(chunk)
        hashes[path.relative_to(base_dir).as_posix()] = sha256.hexdigest()

    with output_path.open("w", encoding="utf-8") as file_obj:
        json.dump(hashes, file_obj, ensure_ascii=False, indent=2, sort_keys=True)

    return str(output_resolved)
```

